import { Formatter, Widget, WidgetPair } from "alias-copy-dep-lab";

/** One member per referenced shape, so each dependency name is read exactly once. */
export interface Panel {
    widget: Widget;
    pair: WidgetPair;
    format: Formatter;
}

/** The entry package's own alias over an object literal, which this run declares. */
export type PanelPair = {
    left: Panel;
    right: Panel;
};

/** A mapped type over the entry package's own operand, resolved by content (D6). */
export declare function draft(panel: Partial<Panel>): void;
